/// The JSON keys a model reads or writes, and the shapes of the nested
/// objects among them. The contract test checks every shape against the
/// server's OpenAPI document, so a server upgrade that renames or drops a
/// field fails a test instead of failing at runtime.
class JsonShape {
  const JsonShape(this.fieldMap, {this.nested = const {}});

  /// Dart field name → JSON key, as generated by json_serializable
  /// (`create_field_map` in build.yaml).
  final Map<String, String> fieldMap;

  /// JSON key → shape of the object under it.
  final Map<String, JsonShape> nested;

  Iterable<String> get keys => fieldMap.values;
}
